  p.armDown=best.ad;p.armFwd=best.f;N3.armClear=best.c;
  // palms down: turn the forearms, then bend the wrists until the hand lies flat, then settle onto the table again
  p.handPron=1.35;p.fingerCurl=0.12;const flatErr=()=>{N3.update(0,0);const s='L',w=B(`arm_${s}_wrist_jnt`).getWorldPosition(new V3()),k=B(`finger_middle_${s}_01_jnt`).getWorldPosition(new V3());return k.y-(w.y-0.6)};
  {let lo=-1.3,hi=1.0;const fl=flatErr;p.handFlex=lo;const sLo=fl();p.handFlex=hi;const sHi=fl();for(let it=0;it<16;it++){const mid=(lo+hi)/2;p.handFlex=mid;const e=fl();if(Math.sign(e)===Math.sign(sLo))lo=mid;else hi=mid}p.handFlex=(lo+hi)/2}
  fitFwd();
  // the sitting pose is the home pose; work out the lying-down pose for falls (back and head on the table)
  N3.sit={legLift:p.legLift,rec:-N3.root.rotation.x,armDown:p.armDown,armFwd:p.armFwd,headPitch:p.headPitch,handFlex:p.handFlex,legSpread:p.legSpread};N3.update(0,0);N3.hipP0=N3.root.parent.worldToLocal(B('spine_M_00_jnt').getWorldPosition(new V3()));
  if(!S.back){S.back=[];for(let i=0;i<P.count;i+=3){let bi=0,bw=0;for(let k=0;k<4;k++){const w=SW.array[i*4+k];if(w>bw){bw=w;bi=SI.array[i*4+k]}}if(/spine_M_0[2-5]|clavicle|head_M|neck/.test(bones[bi].name))S.back.push(i)}}
  const ph=p.headPitch,ad=p.armDown,af=p.armFwd;p.headPitch=-0.12;let lo=N3.sit.rec,hi=1.75;for(let it=0;it<16;it++){const mid=(lo+hi)/2;N3.setRecline(mid);if(minY(S.back)>tableY+0.5)lo=mid;else hi=mid}
