    R('spine_M_01_jnt','x',0.35*crouch);R('arm_L_shldr_jnt','z',1.9*air+0.0);R('arm_R_shldr_jnt','z',-1.9*air);R('arm_L_shldr_jnt','x',0.5*crouch);R('arm_R_shldr_jnt','x',0.5*crouch);
