// ---------- configs ----------
const DEFAULT={body:'female',hair:{style:0,colour:'#2a1a12',size:1,up:0,forward:0},skin:'#d9a67e',nails:'#d9a67e',expression:'smug',faceScale:0.7,faceY:0,hat:{type:'none',colour:'#ffffff',size:1,up:0,forward:0,tilt:0},faceShape:{jaw:1,cheeks:1,chin:1,depth:1},decal:{image:null,size:1,up:0,side:0},ears:{size:1,thickness:1,up:0,forward:0,out:0,twist:0,flare:0},earrings:{type:'none',size:1,colour:null,drop:0,forward:0,angle:0},
  outfit:{shirt:'#2b3350',shorts:'#2a2a2a',belt:'#141414'},
  top:null,legs:null,shoulderL:null,shoulderR:null,
  feet:{type:'flipflops',sole:'#f2efe6',strap:'#e3101c'},
  weapon:null,build:{height:1,footLength:1,toeLength:1,cranium:1,headSize:1,headWidth:1,handSize:1,upperTorso:1,lowerTorso:1,neck:1,shoulders:1,hips:1,upperArm:1,forearm:1,thigh:1,shin:1}};
// proportion sliders: which joints' rest offsets each one scales (a joint's offset is the bone leading to it)
const PROP_BONES={upperTorso:/^spine_M_0[45]_jnt$/,lowerTorso:/^spine_M_0[1-3]_jnt$/,neck:/^head_M_(neck_0[1-3]|head)_jnt$/,shoulders:/^arm_[LR]_shldr_jnt$/,hips:/^leg_[LR]_upr_jnt$/,
  upperArm:/^arm_[LR]_(uprTwist\d+|elbow)_jnt$/,forearm:/^arm_[LR]_(lwrTwist\d+|wrist)_jnt$/,thigh:/^leg_[LR]_(uprTwist\d+|knee)_jnt$/,shin:/^leg_[LR]_(lwrTwist\d+|foot)_jnt$/};
const clone=o=>JSON.parse(JSON.stringify(o));
function merge(base,patch){const out=clone(base);if(!patch)return out;for(const k in patch){const v=patch[k];if(v&&typeof v==='object'&&!Array.isArray(v)&&out[k]&&typeof out[k]==='object')out[k]=Object.assign(out[k],clone(v));else out[k]=v===undefined?out[k]:clone(v)}return out}
function mulberry(a){return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
const BRIGHT=['#e3101c','#ff5c8a','#3fc1ff','#ffcf4a','#4ad4b0','#9b7bff','#ff8a5c','#2ee59d','#ffffff','#141414','#f2efe6','#1e3a5f'];
const HAIRCOL=['#141414','#2a1a12','#4a2a14','#6a3a1a','#9a3f1e','#d6ae58','#e8d7b0','#c8c8c8','#ff5c8a','#3fc1ff','#9b7bff','#e3101c'];

// opts.body: keep that body (and dress it for that body); otherwise a body is picked at random
function randomConfig(seed,opts){const r=seed==null?Math.random:mulberry(typeof seed==='number'?seed:[...String(seed)].reduce((a,c)=>a*31+c.charCodeAt(0)|0,7)),pk=a=>a[Math.floor(r()*a.length)];
  const body=opts&&opts.body?bodyOf(opts):r()<0.5?'female':'male';
  const kit=slot=>{const L=CATALOG.parts[slot].filter(p=>fits(p.id,body));if(!L.length||r()<0.45)return null;const p=pk(L);return {part:p.id,texture:pk(texturesFor(p.set)),colour:r()<0.6?'#ffffff':pk(BRIGHT)}};
  const hs=hairNames(),hOK=hs.map((n,i)=>i).filter(i=>HAIR_FOR[body].includes(hs[i]));
  const c={body,hair:{style:hOK.length?pk(hOK):Math.floor(r()*Math.max(1,hs.length)),colour:pk(HAIRCOL)},skin:pk(SKIN_TONES.slice(1)),nails:pk(NAIL_COLOURS.concat(BRIGHT)),expression:pk(['smug','happy','neutral','curious','relaxed','laugh']),
    outfit:{shirt:pk(NEUTRALS.concat(BRIGHT)),shorts:pk(NEUTRALS),belt:'#141210'},top:kit('top'),legs:kit('legs'),shoulderL:null,shoulderR:null,
    feet:r()<0.7?{type:'flipflops',sole:pk(NEUTRALS.concat(BRIGHT)),strap:pk(BRIGHT)}:r()<0.5?{type:'barefoot'}:(CATALOG.parts.feet.some(p=>fits(p.id,body))?Object.assign({type:'boots'},kit('feet')||(p=>({part:p.id,texture:p.set,colour:'#ffffff'}))(CATALOG.parts.feet.find(p=>fits(p.id,body)))):{type:'barefoot'}),
    weapon:null,
    build:Object.assign({height:+(0.94+r()*0.12).toFixed(3),footLength:+(0.92+r()*0.16).toFixed(3),toeLength:+(0.9+r()*0.2).toFixed(3),cranium:1,headSize:1,headWidth:1},Object.fromEntries(Object.keys(PROP_BONES).map(k=>[k,+(0.94+r()*0.12).toFixed(3)])))};
  if(c.body==='male'){c.nails=c.skin;   // his nails are bare: the same colour as his skin
    // he always wears a tee (short or long sleeves), long trousers and boots
    const tint=()=>r()<0.5?'#ffffff':pk(BRIGHT.concat(NEUTRALS));
    const tees=CATALOG.parts.top.filter(p=>p.id==='gen_tshirt'||p.id==='gen_longsleeve'),longs=CATALOG.parts.legs.filter(p=>LONG_TROUSERS.includes(p.id)),boots=CATALOG.parts.feet.filter(p=>fits(p.id,'male'));
    if(tees.length){const p=pk(tees);c.top={part:p.id,texture:p.set,colour:tint()}}
    if(longs.length){const p=pk(longs);c.legs={part:p.id,texture:pk(texturesFor(p.set)),colour:tint()}}
    if(boots.length){const p=pk(boots);c.feet={type:'boots',part:p.id,texture:pk(texturesFor(p.set)),colour:tint(),height:1,auto:true}}}
  c.earrings=c.body==='female'&&r()<0.5?{type:r()<0.5?'pearls':'hoops',size:1,colour:null,drop:0,forward:0,angle:0}:{type:'none'};
  if(c.feet.type==='boots'&&!c.feet.part)c.feet={type:'barefoot'};if(false/* pauldrons are never picked at random (still available by hand) */&&CATALOG.parts.shoulderL.some(p=>fits(p.id,body))){const p=pk(CATALOG.parts.shoulderL.filter(p=>fits(p.id,body)));c.shoulderL={part:p.id,texture:p.set,colour:'#ffffff'};if(r()<0.7){const q=CATALOG.parts.shoulderR.find(x=>x.set===p.set&&fits(x.id,body))||CATALOG.parts.shoulderR.find(x=>fits(x.id,body));if(q)c.shoulderR={part:q.id,texture:p.set,colour:'#ffffff'}}}
  return c}

// ---------- tinted materials (one per texture + colour, shared) ----------
const TINT={};
function tintArmor(tex,hex){const k='a|'+tex+'|'+hex;if(TINT[k])return TINT[k];const base=armorMaterial(tex);if(!hex||/^#?f{6}$/i.test(hex))return TINT[k]=base;
  const m=aoHook(new THREE.MeshStandardMaterial({map:base.map,roughness:0.85,metalness:0.05,side:THREE.DoubleSide}));m.color.set(hex).convertSRGBToLinear();return TINT[k]=m}
function tintWeapon(key,hex){const k='w|'+key+'|'+hex;if(TINT[k])return TINT[k];const base=weaponMaterial(key);if(!hex||/^#?f{6}$/i.test(hex))return TINT[k]=base;
  const m=new THREE.MeshStandardMaterial({map:base.map,roughness:0.55,metalness:0.15});m.color.set(hex).convertSRGBToLinear();return TINT[k]=m}

// ---------- one Sandy ----------
// standing at ease: a relaxed A-pose. Her rig's rest pose is already an A-pose (upper arms about 49 degrees below level),
// so armDown only lowers them a little further; the old 1.28 assumed a T-pose and swung her arms through her torso.

// ---------- cranium size: one smooth warp (in the head's own frame, cm) applied to her head, her face decal and her hair alike,
// so the hair keeps sitting on the scalp. Nothing below the brow moves; above it everything grows about a point at brow height.
const CRAN={pivot:new THREE.Vector3(0,5.5,1.0),y0:5.5,y1:11.0};
// face shape, in the same warp (head frame, cm; chin at y = -9, brow about +6): jaw and cheek widths, chin length, how far
// the lower face comes forward. The face drawing and any hair below the brow follow it.
const FACE_SHAPE_DEF={jaw:1,cheeks:1,chin:1,depth:1};
function craniumHook(mat,U){if(mat.userData.cran)return;mat.userData.cran=true;const prev=mat.onBeforeCompile;
  mat.onBeforeCompile=(sh,r)=>{if(prev&&prev!==THREE.Material.prototype.onBeforeCompile)prev.call(mat,sh,r);sh.uniforms.crS=U.crS;sh.uniforms.fsJaw=U.jaw;sh.uniforms.fsCheek=U.cheeks;sh.uniforms.fsChin=U.chin;sh.uniforms.fsDepth=U.depth;
    sh.vertexShader='uniform float crS;uniform float fsJaw;uniform float fsCheek;uniform float fsChin;uniform float fsDepth;\n'
      +'vec3 crWarp(vec3 p){'
      +'float wj=1.0-smoothstep(-5.0,1.5,p.y);float wc=smoothstep(-3.0,0.5,p.y)*(1.0-smoothstep(3.5,7.0,p.y));'
      +'p.x*=1.0+(fsJaw-1.0)*wj+(fsCheek-1.0)*wc;'
      +'if(p.y<-3.0)p.y=-3.0+(p.y+3.0)*fsChin;'
      +'float wd=(1.0-smoothstep(4.0,9.0,p.y))*smoothstep('+(CRAN.pivot.z-1).toFixed(2)+','+(CRAN.pivot.z+5).toFixed(2)+',p.z);p.z='+CRAN.pivot.z.toFixed(2)+'+(p.z-'+CRAN.pivot.z.toFixed(2)+')*(1.0+(fsDepth-1.0)*wd);'
      +'float w=smoothstep('+CRAN.y0.toFixed(2)+','+CRAN.y1.toFixed(2)+',p.y);vec3 c=vec3('+CRAN.pivot.toArray().map(v=>v.toFixed(2)).join(',')+');return c+(p-c)*(1.0+(crS-1.0)*w);}\n'
      +sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\ntransformed=crWarp(transformed);')};
  const pk=mat.customProgramCacheKey.bind(mat);mat.customProgramCacheKey=()=>pk()+'|cran2';mat.needsUpdate=true}
function headU(M){return M.cranU||(M.cranU={crS:{value:1},jaw:{value:1},cheeks:{value:1},chin:{value:1},depth:{value:1}})}
function setCranium(M,v){const n3=M.n3,U=headU(M);U.crS.value=Math.min(1.6,Math.max(0.7,+v||1));
  for(const m of [n3.headMesh,n3.faceMesh,n3.hairMesh])if(m){craniumHook(m.material,U);m.frustumCulled=false}}
function setFaceShape(M,f){const U=headU(M);f=Object.assign({},FACE_SHAPE_DEF,f||{});U.jaw.value=Math.min(1.4,Math.max(0.6,+f.jaw||1));U.cheeks.value=Math.min(1.4,Math.max(0.7,+f.cheeks||1));
  U.chin.value=Math.min(1.8,Math.max(0.4,+f.chin||1));U.depth.value=Math.min(1.5,Math.max(0.6,+f.depth||1));setCranium(M,U.crS.value)}

// ---------- face drawing size: scales the face decal's picture about its centre (1 = as drawn) ----------
// faceScale 1 = the drawing at 0.8 of its old size (the old 1 looked far too big); faceY moves it up (+) or down, in face heights
const FACE_UNIT=0.8;
function setFaceScale(M,v,y){const fm=M.n3.faceMesh;if(!fm)return;const U=M.faceU||(M.faceU={value:1}),UY=M.faceUY||(M.faceUY={value:0});U.value=Math.min(1.3,Math.max(0.2,+v||0.7))*FACE_UNIT;UY.value=Math.min(0.4,Math.max(-0.4,+y||0));const mat=fm.material;
  if(mat.userData.fscale)return;mat.userData.fscale=true;const prev=mat.onBeforeCompile;
  mat.onBeforeCompile=(sh,r)=>{if(prev&&prev!==THREE.Material.prototype.onBeforeCompile)prev.call(mat,sh,r);sh.uniforms.faceScale=U;sh.uniforms.faceY=M.faceUY;
    sh.fragmentShader='uniform float faceScale;uniform float faceY;\n'+sh.fragmentShader.replace('#include <map_fragment>',
      'vec2 fuv=(vUv-vec2(0.5,0.5+faceY))/faceScale+0.5;if(fuv.x<0.0||fuv.x>1.0||fuv.y<0.0||fuv.y>1.0)discard;\ndiffuseColor*=texture2D(map,fuv);')};
  const pk=mat.customProgramCacheKey.bind(mat);mat.customProgramCacheKey=()=>pk()+'|fscale';mat.needsUpdate=true}

// ---------- ears: a squashed cylinder each side of her head (head frame, cm), sticking straight out with the flat face forward,
// like a cartoon monkey's, half sunk into her head so each reads as a dome. Size scales the disc, thickness its depth (front-back), up / forward / out move it, twist tips it
// forward or back about the out axis, flare turns its face toward the side.
const EAR_DEF={size:1,thickness:1,up:0,forward:0,out:0,twist:0,flare:0},EAR_BASE={h:6.0,w:5.6,t:1.2,y:1.6,z:-0.6};
// earrings: 'pearls' (a ball at the bottom of each ear, pushed forward) or 'hoops' (a ring hanging from there); colour null =
// pearl white / gold. size scales them, drop lowers them, forward pushes them out in front, angle turns a hoop toward the side.
const RING_DEF={type:'none',size:1,colour:null,drop:0,forward:0,angle:0},RING_COL={pearls:'#f3ede0',hoops:'#d4af37'};
function setEars(M,e,rg){const n3=M.n3,grp=n3.headGroup,head=n3.headMesh;if(!grp||!head)return;e=Object.assign({},EAR_DEF,e||{});rg=Object.assign({},RING_DEF,rg||{});
  if(!M.ears||M.ears[0].parent!==grp){const g=new THREE.CylinderGeometry(0.5,0.5,1,32,1,false);g.rotateX(Math.PI/2);   // unit cylinder, axis along z: a disc facing forward, like a cartoon monkey's ear
    // where the side of her head is at ear height (her head mesh, in the same frame)
    const P=head.geometry.attributes.position;let side=0;for(let i=0;i<P.count;i++){if(Math.abs(P.getY(i)-EAR_BASE.y)<1.6&&Math.abs(P.getZ(i)-EAR_BASE.z)<2.5)side=Math.max(side,Math.abs(P.getX(i)))}
    M.earSide=side||11;
    // each ear: a holder (placed and turned) with the scaled disc and the earrings inside it
    M.ears=[1,-1].map(sg=>{const h=new THREE.Group();h.name='earHolder';h.userData.sg=sg;const m=new THREE.Mesh(g,head.material);m.name='ear';m.castShadow=true;h.add(m);h.userData.ear=m;grp.add(h);return h})}
  for(const h of M.ears){const sg=h.userData.sg,t=EAR_BASE.t*e.thickness,s=e.size,m=h.userData.ear;
    m.scale.set(EAR_BASE.w*s,EAR_BASE.h*s,t);   // sticking straight out from the side of her head, the flat face forward
    h.position.set(sg*(M.earSide+e.out),EAR_BASE.y+e.up,EAR_BASE.z+e.forward);
    h.rotation.set(sg*e.twist,sg*e.flare,0,'YXZ');m.visible=s>0.01;
    // earrings
    const key=rg.type+'|'+rg.size+'|'+(rg.colour||'')+'|'+rg.drop+'|'+rg.forward+'|'+rg.angle+'|'+s+'|'+t;if(h.userData.ringKey===key)continue;h.userData.ringKey=key;
    if(h.userData.ring){h.remove(h.userData.ring);h.userData.ring.traverse(o=>{if(o.geometry)o.geometry.dispose()});h.userData.ring=null}
    if(rg.type!=='pearls'&&rg.type!=='hoops'||s<=0.01)continue;
    const col=new THREE.Color(rg.colour||RING_COL[rg.type]).convertSRGBToLinear(),k=rg.size,lobe=new THREE.Vector3(sg*EAR_BASE.w*s*0.2,-EAR_BASE.h*s*0.5+0.6-rg.drop,t*0.5),r=new THREE.Group();
    if(rg.type==='pearls'){const R=0.95*k,b=new THREE.Mesh(new THREE.SphereGeometry(R,24,16),new THREE.MeshStandardMaterial({color:col,roughness:0.22,metalness:0.08}));
      b.position.copy(lobe).add(new THREE.Vector3(0,-R*0.35,R*0.75+rg.forward));b.castShadow=true;r.add(b)}
    else{const R=2.0*k,tb=0.2*k,o=new THREE.Mesh(new THREE.TorusGeometry(R,tb,12,48),new THREE.MeshStandardMaterial({color:col,roughness:0.3,metalness:0.55}));
      o.position.copy(lobe).add(new THREE.Vector3(0,-R+tb,tb+0.15+rg.forward));o.rotation.y=sg*rg.angle;o.castShadow=true;r.add(o)}
    r.name='earring';h.add(r);h.userData.ring=r}}

// ---------- hand balls, head and hair sizes ----------
function setHands(M,v){const n3=M.n3;v=Math.min(1.8,Math.max(0.4,+v||1));for(const b of n3.handBalls||[]){if(!b.userData.dir)b.userData.dir=b.position.clone().normalize();
  // the ball sinks over the end of the forearm (its centre just past the wrist, so the forearm end is well inside it), whatever its size
  b.scale.setScalar(v);b.position.copy(b.userData.dir).multiplyScalar(HANDBALL.r*v*0.12)}M.handSize=v}
function setHeadSize(M,v,wd){const n3=M.n3,g=n3.headGroup,F=n3.HEADFIT;if(!g)return;v=Math.min(1.5,Math.max(0.6,+v||1));wd=Math.min(1.3,Math.max(0.75,+wd||1));const S=2*0.85*0.8*v;g.scale.set(S*wd,S,S);
  g.position.copy(new THREE.Vector3(0,F.chinY,F.z).multiplyScalar(1-S).applyQuaternion(g.quaternion))}
function setHairSize(M,v,up,fwd){const hm=M.n3.hairMesh,F=M.n3.HEADFIT;if(!hm)return;v=Math.min(1.4,Math.max(0.8,+v||1));const c=new THREE.Vector3(0,F.size/2+F.chinY,F.z);
  hm.scale.setScalar(v);hm.position.copy(c).multiplyScalar(1-v);hm.position.y+=+up||0;hm.position.z+=+fwd||0}

// ---------- chest print: an image projected along her front (bind space, before skinning, so it rides on the cloth) ----------
// Only faces turned to the front take it; the centre is her chest (per body), moved by up / side, sized by size.
const DECAL_AT={female:{y:126.5,s:6.5},male:{y:128.5,s:7.0}},DECAL_SHAPES=['star','heart','bolt','smile','peace'];
const DECAL_TEX={};
function decalCanvas(name){const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');g.translate(128,128);g.lineJoin='round';g.lineCap='round';
  const ink='#ffffff',edge='#141414';g.fillStyle=ink;g.strokeStyle=edge;g.lineWidth=10;
  if(name==='star'){g.beginPath();for(let i=0;i<10;i++){const r=i%2?46:112,a=-Math.PI/2+i*Math.PI/5;g.lineTo(Math.cos(a)*r,Math.sin(a)*r)}g.closePath();g.fill();g.stroke()}
  else if(name==='heart'){g.beginPath();g.moveTo(0,96);g.bezierCurveTo(-150,0,-90,-110,0,-44);g.bezierCurveTo(90,-110,150,0,0,96);g.fill();g.stroke()}
  else if(name==='bolt'){g.beginPath();[[30,-118],[-70,10],[-6,10],[-34,118],[72,-20],[8,-20],[30,-118]].forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.fill();g.stroke()}
  else if(name==='smile'){g.beginPath();g.arc(0,0,108,0,Math.PI*2);g.fill();g.stroke();g.fillStyle=edge;g.beginPath();g.ellipse(-38,-28,12,20,0,0,Math.PI*2);g.ellipse(38,-28,12,20,0,0,Math.PI*2);g.fill();
    g.lineWidth=14;g.beginPath();g.arc(0,8,58,0.15*Math.PI,0.85*Math.PI);g.stroke()}
  else if(name==='peace'){g.lineWidth=18;g.strokeStyle=ink;g.beginPath();g.arc(0,0,100,0,Math.PI*2);g.moveTo(0,-100);g.lineTo(0,100);g.moveTo(0,0);g.lineTo(-71,71);g.moveTo(0,0);g.lineTo(71,71);g.stroke()}
  return c}
function decalTexture(img){if(!img)return null;if(DECAL_TEX[img])return DECAL_TEX[img];let t;
  if(DECAL_SHAPES.includes(img))t=new THREE.CanvasTexture(decalCanvas(img));else t=new THREE.TextureLoader().load(img);
  t.flipY=true;t.anisotropy=4;return DECAL_TEX[img]=t}
function decalHook(mat,U){const prev=mat.onBeforeCompile;mat.onBeforeCompile=(sh,r)=>{if(prev&&prev!==THREE.Material.prototype.onBeforeCompile)prev.call(mat,sh,r);Object.assign(sh.uniforms,U);
    sh.vertexShader='varying vec3 vDecP;varying vec3 vDecN;\n'+sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvDecP=transformed;').replace('#include <beginnormal_vertex>','#include <beginnormal_vertex>\nvDecN=objectNormal;');
    sh.fragmentShader='uniform sampler2D decMap;uniform vec4 decBox;varying vec3 vDecP;varying vec3 vDecN;\n'+sh.fragmentShader.replace('#include <alphamap_fragment>',
      '{vec2 du=(vDecP.xy-decBox.xy)/(2.0*decBox.z)+0.5;if(decBox.w>0.5&&normalize(vDecN).z>0.2&&du.x>0.0&&du.x<1.0&&du.y>0.0&&du.y<1.0){vec4 dc=texture2D(decMap,vec2(1.0-du.x,du.y));diffuseColor.rgb=mix(diffuseColor.rgb,pow(dc.rgb,vec3(2.2)),dc.a);}}\n#include <alphamap_fragment>')};
  const pk=mat.customProgramCacheKey.bind(mat);mat.customProgramCacheKey=()=>pk()+'|decal';mat.needsUpdate=true;return mat}
// put the print on whichever top she has on (called after outfit changes and when the print changes)
function applyDecal(M,d){d=d||{};const tex=decalTexture(d.image);const U=M.decalU||(M.decalU={decMap:{value:null},decBox:{value:new THREE.Vector4()}});
  const at=DECAL_AT[BT(M)];U.decMap.value=tex;U.decBox.value.set(-(+d.side||0),at.y+(+d.up||0),at.s*(+d.size||1),tex?1:0);
  const shirt=M.n3.root.getObjectByName('shirt_geo'),top=M.armorMeshes.body,target=top||(shirt&&shirt.visible?shirt:null);
  for(const m of [shirt,top])if(m&&m.userData.decalOf&&m!==target){m.material=m.userData.decalOf;delete m.userData.decalOf}
  if(!target||!tex)return;
  if(!target.userData.decalOf||target.material.userData.decalBase!==target.userData.decalOf){const base=target.userData.decalOf&&target.material.userData.decalBase===target.userData.decalOf?target.userData.decalOf:target.material;
    const cl=base.clone();cl.onBeforeCompile=base.onBeforeCompile;cl.customProgramCacheKey=base.customProgramCacheKey;   // clone() drops the shader hooks (AO, cloth depth pull): keep them
    const m=decalHook(cl,U);m.userData.decalBase=base;
    target.userData.decalOf=base;target.material=m}}

// ---------- boot height: cut a boot (any footwear part) at a height between its top and just above the ankle ----------
function bootCutHook(mat,U){const prev=mat.onBeforeCompile;mat.onBeforeCompile=(sh,r)=>{if(prev&&prev!==THREE.Material.prototype.onBeforeCompile)prev.call(mat,sh,r);sh.uniforms.bootCut=U;
    sh.vertexShader='varying float vBindY;\n'+sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvBindY=transformed.y;');
    sh.fragmentShader='uniform float bootCut;varying float vBindY;\n'+sh.fragmentShader.replace('void main() {','void main() {\nif(vBindY>bootCut)discard;')};
  const pk=mat.customProgramCacheKey.bind(mat);mat.customProgramCacheKey=()=>pk()+'|bootcut';mat.needsUpdate=true;return mat}
